function validate(input) {
  const [{ Tree = [] }] = input;
  const parent = new Map();
  let roots = 0;
  for (const [id, p] of Tree) {
    if (id === null) return 'Every node needs an id.';
    if (parent.has(id)) return `id ${id} appears twice.`;
    parent.set(id, p);
    if (p === null) roots++;
  }
  if (roots !== 1) return 'The tree needs exactly one root.';
  for (const p of parent.values()) if (p !== null && !parent.has(p)) return `Parent ${p} is not a node.`;
  // With one root and known parents, the links form a tree exactly when every node reaches the root.
  const reaches = new Set();
  for (const start of parent.keys()) {
    const path = [];
    let node = start;
    while (node !== null && !reaches.has(node)) {
      if (path.length > parent.size) return 'The parent links form a cycle.';
      path.push(node);
      node = parent.get(node);
    }
    for (const n of path) reaches.add(n);
  }
  return null;
}

