function generate(rand, size) {
  const small = size === 'small';
  const count = small ? 1 + Math.floor(rand() * 8) : 2000;
  // Distinct ids drawn from a pool, so ids are not always 1..n.
  const pool = Array.from({ length: small ? 20 : 5000 }, (_, i) => i + 1);
  for (let i = 0; i < count; i++) {
    const j = i + Math.floor(rand() * (pool.length - i));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const ids = pool.slice(0, count);
  // Each node after the first hangs under an earlier node; small trees sometimes grow as chains.
  const chain = small && rand() < 0.25;
  const Tree = ids.map((id, i) => [id, i === 0 ? null : ids[chain ? i - 1 : Math.floor(rand() * i)]]);
  // Shuffle the rows so parents do not always come first.
  for (let i = Tree.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Tree[i], Tree[j]] = [Tree[j], Tree[i]];
  }
  return [{ Tree }];
}
